fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // Under the problem statement, we assume the inputs are compatible:
    // either m == n, m == 1, or n == 1.
    assert!(m == n || m == 1 || n == 1, "Incompatible shapes for broadcasting");

    let len = m.max(n);
    let mut out_a = Vec::with_capacity(len);
    let mut out_b = Vec::with_capacity(len);

    for i in 0..len {
        let va = if m == 1 { a[0] } else { a[i] };
        let vb = if n == 1 { b[0] } else { b[i] };
        out_a.push(va);
        out_b.push(vb);
    }

    (out_a, out_b)
}

